SELECT 'gongkao', '主题词', 'kp-xingce-language-reading-main-idea-topic-word', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "主题词定位"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "最高效战法：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "反复出现的高频名词，必然是主旨的灵魂。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、解题步骤"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "如果长文段读不懂，直接圈出出现频率最高的名词。如果四个选项中，只有一个选项包含了这个主题词，连文章都不用看直接秒选！"}]}]}$$ AS jsonb), NULL, '主题词的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "片段阅读", "主题词"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_reading_main_idea_topic_word", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
